#!/usr/bin/env python3
"""Regenerate docs/PATCHES.md from patches/*/patch.json."""
import json, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
out = ["# Patches", "",
       "Every folder in `patches/` is one patch: `patch.json` describes what it adds to the images, `files/` holds",
       "its binaries (sources in `src/`), an optional `hook.py` edits files taken from the OTA itself.",
       "Generated by `tools/gen_patch_docs.py`.", "",
       "| Patch | Default | Needs |", "|---|---|---|"]
details = []
for d in sorted(os.listdir(os.path.join(R, "patches"))):
    f = os.path.join(R, "patches", d, "patch.json")
    if not os.path.isfile(f):
        continue
    p = json.load(open(f))
    dflt = "always" if p.get("required") else ("on" if p.get("default", True) else "off")
    out.append("| `%s` %s | %s | %s |" % (d, p["name"], dflt, ", ".join("`%s`" % r for r in p.get("requires", [])) or "-"))
    details += ["", "## %s" % d, "", "**%s**" % p["name"], "", p.get("description", ""), ""]
    def lst(title, items):
        if items:
            details.extend(["%s:" % title, ""] + ["- `%s`" % i for i in items] + [""])
    lst("Files added to /vendor", [x["dst"] for x in p.get("vendor_files", [])])
    lst("Folders added to /vendor", [x["dst"] for x in p.get("vendor_dirs", [])])
    lst("Removed from /vendor", p.get("vendor_remove", []))
    lst("Removed from /system", p.get("system_remove", []))
    lst("Taken from the sweet ROM", ["%s -> /vendor/%s" % (b["from"], b["to"]) for b in p.get("sweet_blobs", [])])
    lst("Feature markers", p.get("markers", []))
    lst("ueventd", [l for l in p.get("ueventd", []) if not l.startswith("#")])
    init = p.get("init", {})
    lst("init commands", ["%s: %s" % (j["name"], c) for j in init.get("jobs", []) for c in j["cmds"]])
    lst("init services", [" ".join(s["path"]) for s in init.get("services", [])])
    if p.get("hook"):
        details += ["Hook: `%s` (edits files taken from the OTA)." % p["hook"], ""]
open(os.path.join(R, "docs", "PATCHES.md"), "w").write("\n".join(out + details).rstrip() + "\n")
print("docs/PATCHES.md written")
